"""Lab 01-2a: Validate a fine-tuning .jsonl file BEFORE you pay for a customization job. Runs locally.

Checks the two text formats documented for Bedrock fine-tuning:
  * prompt/completion      {"prompt": "...", "completion": "..."}
  * Converse-style         {"schemaVersion": "bedrock-conversation-2024", "system": [...], "messages": [...]}
and reports: record count, empty fields, duplicate prompts, role-order problems, estimated tokens.

Run:  python validate_training_data.py sample_train.jsonl [--min-records 100]
Notes: * Token estimate uses ~6 characters/token, the planning ratio AWS gives for dataset sizing.
       * Per-model minimums/maximums differ (e.g. documented minimums were 32 records for Claude 3 Haiku and
         100 for Llama 3.x). Check the CURRENT page for your model and pass --min-records accordingly.
"""
import argparse
import json
import sys
from collections import Counter

CHARS_PER_TOKEN = 6


def text_of(blocks) -> str:
    if isinstance(blocks, str):
        return blocks
    return " ".join(b.get("text", "") for b in blocks if isinstance(b, dict))


def check_record(rec: dict) -> tuple[list[str], str, int]:
    """Return (problems, dedupe_key, char_count)."""
    problems: list[str] = []
    if "prompt" in rec or "completion" in rec:
        prompt, completion = rec.get("prompt"), rec.get("completion")
        if not isinstance(prompt, str) or not prompt.strip():
            problems.append("empty or missing 'prompt'")
        if not isinstance(completion, str) or not completion.strip():
            problems.append("empty or missing 'completion'")
        return problems, str(prompt), len(str(prompt)) + len(str(completion))

    if "messages" in rec:
        msgs = rec["messages"]
        if not isinstance(msgs, list) or len(msgs) < 2:
            return ["'messages' needs at least a user and an assistant turn"], "", 0
        expected = "user"
        chars = 0
        for i, m in enumerate(msgs):
            role = m.get("role")
            if role != expected:
                problems.append(f"message {i}: expected role '{expected}', got '{role}'")
            expected = "assistant" if role == "user" else "user"
            body = text_of(m.get("content", ""))
            if not body.strip():
                problems.append(f"message {i}: empty content")
            chars += len(body)
        if msgs[-1].get("role") != "assistant":
            problems.append("last message must be the assistant's target answer")
        if "system" in rec:
            chars += len(text_of(rec["system"]))
        return problems, text_of(msgs[0].get("content", "")), chars

    return ["unrecognised format: expected 'prompt'/'completion' or 'messages'"], "", 0


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("path")
    ap.add_argument("--min-records", type=int, default=100)
    args = ap.parse_args()

    total, bad, chars_list = 0, 0, []
    seen: Counter = Counter()
    with open(args.path, encoding="utf-8") as fh:
        for line_no, line in enumerate(fh, start=1):
            if not line.strip():
                continue
            total += 1
            try:
                rec = json.loads(line)
            except json.JSONDecodeError as exc:
                bad += 1
                print(f"line {line_no}: invalid JSON ({exc.msg})")
                continue
            problems, key, chars = check_record(rec)
            if key.strip():  # empty prompts are already reported as problems; don't also call them "duplicates"
                seen[key] += 1
            chars_list.append(chars)
            if problems:
                bad += 1
                for p in problems:
                    print(f"line {line_no}: {p}")

    dupes = sum(c - 1 for c in seen.values() if c > 1)
    est_tokens = [c // CHARS_PER_TOKEN for c in chars_list]
    print("\n--- summary ---")
    print(f"records            : {total}")
    print(f"records with issues: {bad}")
    print(f"duplicate prompts  : {dupes}")
    if est_tokens:
        print(f"est. tokens/record : avg {sum(est_tokens)//len(est_tokens)}, max {max(est_tokens)}")
        print(f"est. training tokens (1 epoch): {sum(est_tokens)}  (billing = tokens x epochs)")
    if total < args.min_records:
        print(f"WARNING: only {total} records; this model family may need at least {args.min_records}.")
    return 1 if bad else 0


if __name__ == "__main__":
    sys.exit(main())

